    if worked == "c":
        span.set_attribute("do.via", rungs[-1].get("via") or "")

    if worked:
        result = {"success": True, "changed": True, "rung": worked, "url": url}
        if worked == "c":
            result["via"] = rungs[-1].get("via")
        if worked != "a":
            result["note"] = "The first try had no effect; a retry worked."
