// Shapes returned by GET /api/runs/[id]. Shared by the API route and the run page.

export type RunStatus = "queued" | "running" | "done" | "failed";
export type Outcome = "achieved" | "gave_up" | "blocked" | "max_steps" | "error";

export type Run = {
  id: string;
  url: string;
  goal: string;
  status: RunStatus;
  outcome: Outcome | null;
  reason: string | null;
  cost_usd: number | string | null;
  brain_model: string | null;
  created_at: string;
  started_at: string | null;
  finished_at: string | null;
};

export type Step = {
  idx: number;
  tool: string;
  thought: string | null;
  input: Record<string, unknown> | null;
  result: Record<string, unknown> | null;
  url: string | null;
  screenshot_path: string | null;
  created_at: string;
};

export type Friction = {
  id: number;
  step_idx: number | null;
  kind: "site" | "agent_issue";
  severity: "low" | "medium" | "high" | null;
  expected: string | null;
  happened: string | null;
};

export type RunDetails = { run: Run; steps: Step[]; frictions: Friction[] };

export type ApiError = { error: string; message: string };

export const RUN_COLUMNS =
  "id, url, goal, status, outcome, reason, cost_usd, brain_model, created_at, started_at, finished_at";
export const STEP_COLUMNS = "idx, tool, thought, input, result, url, screenshot_path, created_at";
export const FRICTION_COLUMNS = "id, step_idx, kind, severity, expected, happened";

import { supabase } from "@/lib/supabase";
import { checkTargetUrl } from "@/lib/target-url";
import { clientIp, hashIp } from "@/lib/visitor";

const DEFAULT_GOAL = "Work out what this product does and try its main feature as a first-time visitor.";
const MAX_GOAL_LENGTH = 500;
const MAX_QUEUED = 20;
const MAX_RUNS_PER_HOUR = 5;

function fail(status: number, error: string, message: string, headers?: HeadersInit) {
  return Response.json({ error, message }, { status, headers });
}

export async function POST(request: Request) {
  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return fail(400, "invalid_request", "The request could not be read. Reload the page and try again.");
  }
  const { url, goal, permission } = (body ?? {}) as Record<string, unknown>;

  if (permission !== true) {
    return fail(400, "permission_required", "Confirm that this is your app or that you have permission to test it.");
  }
  if (typeof url !== "string") {
    return fail(400, "invalid_url", "Enter your app's address.");
  }
  if (goal !== undefined && goal !== null && typeof goal !== "string") {
    return fail(400, "invalid_request", "The goal must be text.");
  }
  const goalText = (goal ?? "").trim();
  if (goalText.length > MAX_GOAL_LENGTH) {
    return fail(400, "goal_too_long", `Keep the goal under ${MAX_GOAL_LENGTH} characters.`);
  }

  const target = await checkTargetUrl(url);
  if (!target.ok) return fail(400, "invalid_url", target.message);

  const { data, error } = await supabase().rpc("enqueue_web_run", {
    p_url: target.url,
    p_goal: goalText || DEFAULT_GOAL,
    p_ip_hash: hashIp(clientIp(request.headers)),
    p_max_queued: MAX_QUEUED,
    p_max_per_hour: MAX_RUNS_PER_HOUR,
  });
  if (error) {
    console.error("enqueue_web_run failed:", error.message);
    return fail(500, "server_error", "Something went wrong on our side. Please try again in a minute.");
  }

  const result = data as { id?: string; error?: string; retry_after_seconds?: number };
  if (result.error === "queue_full") {
    return fail(
      503,
      "queue_full",
      "Too many runs are waiting right now. Please try again in a few minutes.",
      { "Retry-After": "300" },
    );
  }
  if (result.error === "rate_limited") {
    const seconds = Math.max(60, result.retry_after_seconds ?? 3600);
    const minutes = Math.ceil(seconds / 60);
    return fail(
      429,
      "rate_limited",
      `You've started ${MAX_RUNS_PER_HOUR} runs in the last hour. You can start another in about ${minutes} minute${minutes === 1 ? "" : "s"}.`,
      { "Retry-After": String(seconds) },
    );
  }
  if (!result.id) {
    console.error("enqueue_web_run returned no id");
    return fail(500, "server_error", "Something went wrong on our side. Please try again in a minute.");
  }
  return Response.json({ id: result.id }, { status: 201 });
}

import { supabase } from "@/lib/supabase";
import { FRICTION_COLUMNS, RUN_COLUMNS, STEP_COLUMNS } from "@/lib/types";

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const NO_STORE = { "Cache-Control": "no-store" };

function fail(status: number, error: string, message: string) {
  return Response.json({ error, message }, { status, headers: NO_STORE });
}

export async function GET(_request: Request, ctx: RouteContext<"/api/runs/[id]">) {
  const { id } = await ctx.params;
  if (!UUID.test(id)) return fail(404, "not_found", "We couldn't find that run.");

  // Only selected columns: the visitor's IP hash and the raw worker error stay private.
  const db = supabase();
  const [run, steps, frictions] = await Promise.all([
    db.from("runs").select(RUN_COLUMNS).eq("id", id).maybeSingle(),
    db.from("steps").select(STEP_COLUMNS).eq("run_id", id).order("idx"),
    db.from("frictions").select(FRICTION_COLUMNS).eq("run_id", id).order("step_idx").order("id"),
  ]);

  const error = run.error ?? steps.error ?? frictions.error;
  if (error) {
    console.error("Reading run failed:", error.message);
    return fail(500, "server_error", "Something went wrong on our side. Retrying shortly.");
  }
  if (!run.data) return fail(404, "not_found", "We couldn't find that run.");

  return Response.json({ run: run.data, steps: steps.data, frictions: frictions.data }, { headers: NO_STORE });
}

